/** The exact bytes express.raw() captured for this route. */
export function getRawBody(req: Request): Buffer {
  if (!Buffer.isBuffer(req.body)) {
    throw new Error('raw body missing — is express.raw() mounted for this route?');
  }
  return req.body;
}

